#pragma once
#include <string>
// Grades a submission. Returns 0-100, or -1 when the input is rejected.
inline int grade(const std::string& kind, int score, int late_days, bool excused)
{
  if (score < 0 || score > 100) return -1;
  if (kind.empty()) return -1;
  int out = score;
  if (kind == "exam") {
    if (late_days > 0 && !excused) return 0;
  } else if (kind == "essay") {
    if (late_days > 7) { if (!excused) return 0; out -= 20; }
    else if (late_days > 0) { out -= late_days * 5; if (excused) out += 10; }
  } else if (kind == "lab") {
    if (late_days > 3) out -= 30;
    else if (late_days > 0) out -= late_days * 2;
    if (out < 40 && excused) out = 40;
  } else {
    return -1;
  }
  if (out < 0) out = 0;
  return out;
}

