#undef NDEBUG
#include "rules.hpp"
#include <cassert>

// One case per distinct decision outcome in grade().

static void rejects() {
  assert(grade("exam", -1, 0, false) == -1);   // score below range
  assert(grade("exam", 101, 0, false) == -1);  // score above range
  assert(grade("", 50, 0, false) == -1);       // empty kind
  assert(grade("quiz", 50, 0, false) == -1);   // unknown kind
  assert(grade("exam", 0, 0, false) == 0);     // score lower bound accepted
  assert(grade("exam", 100, 0, false) == 100); // score upper bound accepted
}

static void exams() {
  assert(grade("exam", 90, 0, false) == 90); // on time
  assert(grade("exam", 90, 2, false) == 0);  // late, not excused
  assert(grade("exam", 90, 2, true) == 90);  // late, excused -> no penalty
}

static void essays() {
  assert(grade("essay", 90, 0, false) == 90); // on time
  assert(grade("essay", 90, 3, false) == 75); // 5/day
  assert(grade("essay", 90, 3, true) == 85);  // 5/day, +10 excused
  assert(grade("essay", 90, 7, false) == 55); // last day of the 5/day band
  assert(grade("essay", 90, 8, false) == 0);  // past 7 days, not excused
  assert(grade("essay", 90, 8, true) == 70);  // past 7 days, excused -> flat -20
  assert(grade("essay", 10, 5, false) == 0);  // penalty below zero is clamped
  assert(grade("essay", 5, 6, true) == 0);    // excused bonus still clamps at 0
}

static void labs() {
  assert(grade("lab", 90, 0, false) == 90); // on time
  assert(grade("lab", 90, 2, false) == 86); // 2/day
  assert(grade("lab", 90, 3, false) == 84); // last day of the 2/day band
  assert(grade("lab", 90, 4, false) == 60); // past 3 days -> flat -30
  assert(grade("lab", 50, 4, false) == 20); // ends under 40, not excused
  assert(grade("lab", 50, 4, true) == 40);  // ends under 40, excused -> floor
  assert(grade("lab", 90, 4, true) == 60);  // excused but already over 40
  assert(grade("lab", 10, 5, false) == 0);  // negative is clamped
  assert(grade("lab", 10, 5, true) == 40);  // excused floor applies before clamp
}

int main() {
  rejects();
  exams();
  essays();
  labs();
  return 0;
}

